<section class="heroes">
  <header class="heroes__header">
    <h1 hlmH1>Roster</h1>
    <p hlmMuted>Example data. Every hero on the books, strongest first.</p>
  </header>

  <div class="heroes__filters" role="search">
    <label hlmLabel for="roster-search" class="heroes__label">Search heroes</label>
